/**
 * Product Search Script (Node.js)
 * Scrapes Google Shopping for products similar to a given query.
 *
 * Usage:
 *   node product_search.js --query "portable bluetooth speaker" --output results.json
 *
 * NOTE: Web scraping may violate a site's Terms of Service.
 * This is provided for educational purposes.
 */

const https = require("https");
const http = require("http");
const fs = require("fs");
const { URL } = require("url");

// ---------------------------------------------------------------------------
// Parse CLI arguments
// ---------------------------------------------------------------------------
function parseArgs() {
  const args = process.argv.slice(2);
  const opts = {
    query: "portable bluetooth speaker",
    maxResults: 10,
    output: null,
  };
  for (let i = 0; i < args.length; i++) {
    if (args[i] === "--query" && args[i + 1]) opts.query = args[++i];
    if (args[i] === "--max-results" && args[i + 1]) opts.maxResults = parseInt(args[++i], 10);
    if (args[i] === "--output" && args[i + 1]) opts.output = args[++i];
  }
  return opts;
}

// ---------------------------------------------------------------------------
// Simple HTTP GET (follows redirects)
// ---------------------------------------------------------------------------
function httpGet(urlStr, headers = {}, maxRedirects = 5) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(urlStr);
    const lib = parsed.protocol === "https:" ? https : http;
    const options = {
      hostname: parsed.hostname,
      path: parsed.pathname + parsed.search,
      headers: {
        "User-Agent":
          "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
        "Accept-Language": "en-US,en;q=0.9",
        ...headers,
      },
    };
    lib.get(options, (res) => {
      if ([301, 302, 303, 307, 308].includes(res.statusCode) && res.headers.location && maxRedirects > 0) {
        const redirectUrl = new URL(res.headers.location, urlStr).toString();
        return resolve(httpGet(redirectUrl, headers, maxRedirects - 1));
      }
      let data = "";
      res.on("data", (chunk) => (data += chunk));
      res.on("end", () => resolve({ statusCode: res.statusCode, body: data }));
    }).on("error", reject);
  });
}

// ---------------------------------------------------------------------------
// Minimal HTML text extractor (no external dependency)
// ---------------------------------------------------------------------------
function extractText(html) {
  return html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, "")
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "")
    .replace(/<[^>]+>/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

// ---------------------------------------------------------------------------
// Parse Google Shopping HTML for product listings
// ---------------------------------------------------------------------------
function parseShoppingResults(html, maxResults) {
  const products = [];

  // Strategy 1: Look for structured product data in script tags
  const jsonLdRegex = /<script[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/gi;
  let match;
  while ((match = jsonLdRegex.exec(html)) !== null) {
    try {
      const data = JSON.parse(match[1]);
      if (data["@type"] === "Product" || (Array.isArray(data) && data[0]?.["@type"] === "Product")) {
        const items = Array.isArray(data) ? data : [data];
        for (const item of items) {
          products.push({
            name: item.name || "N/A",
            price: item.offers?.price || item.offers?.lowPrice || "N/A",
            currency: item.offers?.priceCurrency || "USD",
            description: (item.description || "").slice(0, 150),
          });
        }
      }
    } catch {}
  }

  // Strategy 2: Regex-based extraction of product-like blocks
  if (products.length === 0) {
    // Look for common product title+price patterns in shopping results
    // Google Shopping wraps items in divs; titles are often in <h3> or <a> with aria-label
    const titleRegex = /<(?:h3|h4)[^>]*class="[^"]*"[^>]*>(.*?)<\/(?:h3|h4)>/gi;
    const priceRegex = /\$\d{1,4}(?:\.\d{2})?/g;

    const titles = [];
    let m;
    while ((m = titleRegex.exec(html)) !== null) {
      const text = extractText(m[1]);
      if (text.length > 5 && text.length < 200) {
        titles.push(text);
      }
    }

    const prices = html.match(priceRegex) || [];

    for (let i = 0; i < Math.min(titles.length, maxResults); i++) {
      products.push({
        name: titles[i],
        price: prices[i] || "N/A",
        currency: "USD",
        description: "",
      });
    }
  }

  // Strategy 3: Extract aria-label product names
  if (products.length === 0) {
    const ariaRegex = /aria-label="([^"]{10,150})"/gi;
    const seen = new Set();
    let am;
    while ((am = ariaRegex.exec(html)) !== null) {
      const label = am[1];
      if (
        !seen.has(label) &&
        (label.toLowerCase().includes("speaker") ||
          label.toLowerCase().includes("bluetooth") ||
          label.toLowerCase().includes("portable"))
      ) {
        seen.add(label);
        products.push({ name: label, price: "N/A", currency: "USD", description: "" });
      }
    }
  }

  return products.slice(0, maxResults);
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
async function main() {
  const opts = parseArgs();
  const query = encodeURIComponent(opts.query);
  const url = `https://www.google.com/search?q=${query}&tbm=shop&num=${opts.maxResults}`;

  console.log(`\n🔍 Scraping Google Shopping for: '${opts.query}'\n`);

  try {
    const { statusCode, body } = await httpGet(url);

    if (statusCode !== 200) {
      console.log(`⚠️  Received HTTP ${statusCode}. Google may be blocking the request.`);
      console.log("   Consider using an API service like SerpAPI for reliable results.\n");
    }

    const products = parseShoppingResults(body, opts.maxResults);

    if (products.length === 0) {
      console.log("No products found (page structure may have changed or request was blocked).");
      console.log("Tip: For reliable results, use SerpAPI (https://serpapi.com) or similar services.\n");

      // Save empty results if output specified
      if (opts.output) {
        const result = {
          query: opts.query,
          timestamp: new Date().toISOString(),
          note: "No results scraped — Google may have blocked the request or changed its HTML structure.",
          suggestion: "Use an API like SerpAPI, or Best Buy Product API for reliable results.",
          products: [],
        };
        fs.writeFileSync(opts.output, JSON.stringify(result, null, 2));
        console.log(`📄 Empty results saved to ${opts.output}`);
      }
      return;
    }

    console.log(`Found ${products.length} result(s):\n`);
    console.log("-".repeat(80));
    products.forEach((p, i) => {
      console.log(`  ${i + 1}. ${p.name}`);
      console.log(`     Price: ${typeof p.price === "number" ? `$${p.price}` : p.price}`);
      if (p.description) console.log(`     Info:  ${p.description}`);
      console.log("-".repeat(80));
    });

    if (opts.output) {
      const result = {
        query: opts.query,
        timestamp: new Date().toISOString(),
        resultCount: products.length,
        products,
      };
      fs.writeFileSync(opts.output, JSON.stringify(result, null, 2));
      console.log(`\n✅ Results saved to ${opts.output}`);
    }
  } catch (err) {
    console.error(`❌ Error: ${err.message}`);
    process.exit(1);
  }
}

main();

