  };
  for (let i = 0; i < args.length; i++) {
    if (args[i] === "--query" && args[i + 1]) opts.query = args[++i];
    if (args[i] === "--max-results" && args[i + 1]) opts.maxResults = parseInt(args[++i], 10);
    if (args[i] === "--output" && args[i + 1]) opts.output = args[++i];
  }
