}

// ---------------------------------------------------------------------------
// Parse CLI arguments
// ---------------------------------------------------------------------------
function parseArgs() {
  const args = process.argv.slice(2);
  const opts = {
    method: "scrape",
    query: "portable bluetooth speaker",
    maxResults: 10,
    output: null,
    apiKey: null,
  };
  for (let i = 0; i < args.length; i++) {
    if (args[i] === "--method" && args[i + 1]) opts.method = args[++i];
    if (args[i] === "--query" && args[i + 1]) opts.query = args[++i];
    if (args[i] === "--max-results" && args[i + 1]) opts.maxResults = parseInt(args[++i], 10);
    if (args[i] === "--output" && args[i + 1]) opts.output = args[++i];
    if (args[i] === "--api-key" && args[i + 1]) opts.apiKey = args[++i];
  }
  return opts;
}

// ---------------------------------------------------------------------------
// Best Buy API search
// ---------------------------------------------------------------------------
async function searchBestBuyAPI(query, apiKey, maxResults) {
  const searchQuery = encodeURIComponent(query);
  const url =
    `https://api.bestbuy.com/v1/products((search=${searchQuery}))` +
    `?apiKey=${apiKey}` +
    `&show=sku,name,salePrice,customerReviewAverage,customerReviewCount,shortDescription,url` +
    `&sort=customerReviewAverage.dsc` +
    `&pageSize=${maxResults}` +
    `&format=json`;

  console.log(`\n🔍 Searching Best Buy API for: '${query}'\n`);

  const { statusCode, body } = await httpGet(url);
  let data;
  try {
    data = JSON.parse(body);
  } catch {
    console.log(`⚠️  HTTP ${statusCode} — Could not parse response.`);
    console.log("   The API key may be invalid or the request was rejected.");
    console.log(`\n   Raw response (first 500 chars): ${body.slice(0, 500)}\n`);
    return [];
  }

  if (statusCode !== 200 || data.error) {
    console.log(`⚠️  HTTP ${statusCode}: ${data.error?.message || data.message || "Request failed"}`);
    console.log("   A valid Best Buy API key is required.");
    console.log("   Get a free key at: https://developer.bestbuy.com\n");
    return [];
  }

  const products = (data.products || []).map((p) => ({
    name: p.name || "N/A",
    price: p.salePrice || "N/A",
    rating: p.customerReviewAverage || "N/A",
    reviewCount: p.customerReviewCount || 0,
    description: (p.shortDescription || "").slice(0, 150),
    url: p.url || "N/A",
  }));

  return products;
}

